export const guideCombatStepLabelsProvenance=Object.fromEntries(Object.keys(guideCombatStepLabels).map(locale=>[locale,"gpt"])) as Record<Locale,"gpt">;
const onboardingSteps=(gettingStarted:string,returningPlayer:string)=>{const first=gettingStarted.split("|"),second=returningPlayer.split("|");if(first.length!==5||second.length!==4)throw new Error("Onboarding guides need five and four specific steps");return {"getting-started":first,"returning-player":second} as const};
export const guideOnboardingStepLabels:Record<Locale,Readonly<Record<"getting-started"|"returning-player",readonly string[]>>>={
  "en-US":onboardingSteps("Choose a first destination with the map filters and accessible result list, keeping dense layers narrowed to the markers you need.|Compare Pals by their current elements and work suitability, and choose candidates for the first roles without inventing a performance tier.|Review the technology order, unlocks, and prerequisites so the next target is reachable before spending points or materials.|Set the essential work roles, minimum levels, and team limit in the base planner, then inspect the generated candidates.|Select the exact crafting recipe, calculate direct and expanded material demand, and stop where multiple recipes still require your choice.","Review the current quest catalog, objectives, and reward links, then make your own revisit list.|Compare technology prerequisites, unlocks, and dependents before committing saved points or materials.|Inspect expedition stages and reward candidates without inferring probabilities that are not provided.|Rebuild your destination shortlist from the current map filters and result list instead of relying on remembered locations."),
  "ko-KR":onboardingSteps("지도 필터와 접근 가능한 결과 목록에서 첫 목적지를 고르고, 밀집된 레이어는 필요한 마커만 남기세요.|현재 속성과 작업 적성을 기준으로 팰을 비교하고, 임의의 성능 등급 없이 첫 역할 후보를 고르세요.|포인트나 재료를 쓰기 전에 기술 순서, 해금 항목, 선행 조건을 확인하여 다음 목표에 도달할 수 있는지 점검하세요.|거점 플래너에서 필수 작업 역할, 최소 레벨, 팀 제한을 설정하고 생성된 후보를 확인하세요.|정확한 제작법을 선택해 직접·확장 재료 수요를 계산하고, 여러 제작법 중 선택이 필요한 지점에서는 확장을 멈추세요.","현재 퀘스트 목록과 목표·보상 연결을 확인한 뒤 직접 다시 살펴볼 목록을 만드세요.|모아 둔 포인트나 재료를 쓰기 전에 기술의 선행 조건, 해금 항목, 후속 기술을 비교하세요.|제공되지 않은 확률을 추론하지 말고 원정 단계와 보상 후보를 확인하세요.|기억에 의존하지 말고 현재 지도 필터와 결과 목록에서 목적지 후보를 다시 구성하세요."),
  "ja-JP":onboardingSteps("マップのフィルターと利用しやすい結果一覧で最初の目的地を選び、密集したレイヤーは必要なマーカーだけに絞ります。|現在の属性と作業適性でパルを比較し、独自の性能ランクを作らずに最初の役割候補を選びます。|ポイントや素材を使う前に、テクノロジーの順序、アンロック、前提条件を確認して次の目標に到達できるか確かめます。|拠点プランナーで必要な作業役割、最低レベル、チーム上限を設定し、生成された候補を確認します。|使用するレシピを明示して直接・展開後の素材需要を計算し、複数レシピから選択が必要な箇所では展開を止めます。","現在のクエスト一覧、目標、報酬リンクを確認し、自分で再訪リストを作ります。|保存していたポイントや素材を使う前に、テクノロジーの前提条件、アンロック、後続項目を比較します。|提示されていない確率を推測せず、遠征の段階と報酬候補を確認します。|記憶した場所に頼らず、現在のマップフィルターと結果一覧から目的地候補を作り直します。"),
  "zh-CN":onboardingSteps("使用地图筛选器和无障碍结果列表选择第一个目的地，并把密集图层缩小到所需标记。|按当前属性和工作适应性比较帕鲁，在不虚构性能等级的情况下选择首批岗位候选。|花费科技点或材料前查看科技顺序、解锁内容和前置条件，确认下一个目标可以达成。|在据点规划器中设置必要工作、最低等级和队伍上限，然后检查生成的候选。|选择确切配方，计算直接及展开后的材料需求；遇到多个有效配方时停止并由你选择。","查看当前任务目录、目标和奖励链接，再制作自己的重访清单。|投入已保存的科技点或材料前，比较科技前置条件、解锁内容和后续项目。|查看远征阶段和奖励候选，不推断未提供的概率。|不要依赖记忆中的位置，使用当前地图筛选器和结果列表重新建立目的地候选。"),
  "zh-TW":onboardingSteps("使用地圖篩選器與無障礙結果清單選擇第一個目的地，並將密集圖層縮小到所需標記。|依目前屬性與工作適性比較帕魯，不自創效能等級，選出首批職務候選。|花費科技點或材料前檢查科技順序、解鎖內容與前置條件，確認下一個目標可以達成。|在據點規劃器中設定必要工作、最低等級與隊伍上限，再檢查產生的候選。|選擇確切配方，計算直接與展開後的材料需求；遇到多個有效配方時停止並由你選擇。","查看目前任務目錄、目標與獎勵連結，再建立自己的重訪清單。|投入已保存的科技點或材料前，比較科技前置條件、解鎖內容與後續項目。|查看遠征階段與獎勵候選，不推斷未提供的機率。|不要依賴記憶中的位置，使用目前地圖篩選器與結果清單重新建立目的地候選。"),
  "fr-FR":onboardingSteps("Choisissez une première destination avec les filtres de carte et la liste de résultats accessible, en limitant les couches denses aux marqueurs utiles.|Comparez les Pals selon leurs éléments et aptitudes au travail actuels, puis choisissez les premiers rôles sans inventer de palier de performance.|Vérifiez l’ordre des technologies, les déblocages et les prérequis afin que le prochain objectif soit accessible avant de dépenser points ou matériaux.|Définissez les rôles essentiels, les niveaux minimaux et la limite d’équipe dans le planificateur de base, puis examinez les candidats générés.|Choisissez la recette exacte, calculez les besoins directs et développés, puis arrêtez-vous lorsqu’un choix entre plusieurs recettes reste nécessaire.","Consultez le catalogue actuel des quêtes, leurs objectifs et leurs récompenses, puis créez votre propre liste à revisiter.|Comparez les prérequis, déblocages et dépendances des technologies avant d’engager vos points ou matériaux conservés.|Examinez les étapes d’expédition et les récompenses possibles sans déduire de probabilités non fournies.|Recréez votre liste de destinations avec les filtres et résultats actuels de la carte plutôt qu’avec vos souvenirs."),
  "it-IT":onboardingSteps("Scegli una prima destinazione con i filtri della mappa e l’elenco accessibile dei risultati, limitando i livelli densi ai soli indicatori necessari.|Confronta i Pal per elemento e attitudine al lavoro attuali e scegli i candidati per i primi ruoli senza inventare fasce di prestazione.|Controlla ordine, sblocchi e prerequisiti delle tecnologie prima di spendere punti o materiali, così che il prossimo obiettivo sia raggiungibile.|Imposta ruoli essenziali, livelli minimi e limite della squadra nel pianificatore della base, quindi esamina i candidati generati.|Scegli la ricetta esatta, calcola la richiesta diretta ed espansa di materiali e fermati dove più ricette richiedono ancora una scelta.","Consulta il catalogo attuale di missioni, obiettivi e collegamenti alle ricompense, quindi crea il tuo elenco da rivedere.|Confronta prerequisiti, sblocchi e dipendenze delle tecnologie prima di usare punti o materiali conservati.|Esamina le fasi delle spedizioni e le ricompense candidate senza dedurre probabilità non fornite.|Ricostruisci l’elenco delle destinazioni con i filtri e i risultati attuali della mappa invece di affidarti ai luoghi ricordati."),
  "de-DE":onboardingSteps("Wähle mit den Kartenfiltern und der zugänglichen Ergebnisliste ein erstes Ziel und begrenze dichte Ebenen auf die benötigten Markierungen.|Vergleiche Pals nach ihren aktuellen Elementen und Arbeitseignungen und wähle Kandidaten für die ersten Rollen, ohne Leistungsstufen zu erfinden.|Prüfe Technologiereihenfolge, Freischaltungen und Voraussetzungen, bevor du Punkte oder Materialien ausgibst, damit das nächste Ziel erreichbar ist.|Lege im Basisplaner notwendige Arbeitsrollen, Mindeststufen und das Teamlimit fest und prüfe anschließend die erzeugten Kandidaten.|Wähle das genaue Rezept, berechne direkten und erweiterten Materialbedarf und stoppe, wenn mehrere Rezepte noch deine Entscheidung verlangen.","Prüfe den aktuellen Questkatalog samt Zielen und Belohnungsverknüpfungen und erstelle danach deine eigene Wiederkehrliste.|Vergleiche Voraussetzungen, Freischaltungen und abhängige Technologien, bevor du gesparte Punkte oder Materialien einsetzt.|Prüfe Expeditionsstufen und mögliche Belohnungen, ohne nicht angegebene Wahrscheinlichkeiten abzuleiten.|Erstelle deine Zielliste mit den aktuellen Kartenfiltern und Ergebnissen neu, statt dich auf erinnerte Orte zu verlassen."),
  "es-ES":onboardingSteps("Elige un primer destino con los filtros del mapa y la lista de resultados accesible, limitando las capas densas a los marcadores necesarios.|Compara los Pals por sus elementos y aptitudes laborales actuales y elige candidatos para los primeros puestos sin inventar niveles de rendimiento.|Revisa el orden, los desbloqueos y los requisitos de tecnología antes de gastar puntos o materiales para que el siguiente objetivo sea alcanzable.|Configura los trabajos esenciales, los niveles mínimos y el límite del equipo en el planificador de base y revisa los candidatos generados.|Elige la receta exacta, calcula la demanda directa y ampliada de materiales y detente cuando varias recetas aún requieran tu elección.","Revisa el catálogo actual de misiones, sus objetivos y enlaces de recompensas, y crea tu propia lista para volver.|Compara requisitos, desbloqueos y tecnologías dependientes antes de usar puntos o materiales guardados.|Examina las fases de expedición y las posibles recompensas sin deducir probabilidades que no se proporcionan.|Reconstruye tu lista de destinos con los filtros y resultados actuales del mapa en vez de confiar en ubicaciones recordadas."),
  "es-419":onboardingSteps("Elige un primer destino con los filtros del mapa y la lista accesible de resultados, limitando las capas densas a los marcadores necesarios.|Compara los Pals por sus elementos y aptitudes de trabajo actuales y elige candidatos para los primeros roles sin inventar niveles de rendimiento.|Revisa el orden, los desbloqueos y los requisitos de tecnología antes de gastar puntos o materiales para que el siguiente objetivo sea alcanzable.|Configura los trabajos esenciales, los niveles mínimos y el límite del equipo en el planificador de base y revisa los candidatos generados.|Elige la receta exacta, calcula la demanda directa y ampliada de materiales y detente cuando varias recetas aún requieran tu elección.","Revisa el catálogo actual de misiones, sus objetivos y enlaces de recompensas, y crea tu propia lista para volver.|Compara requisitos, desbloqueos y tecnologías dependientes antes de usar puntos o materiales guardados.|Revisa las etapas de expedición y las recompensas posibles sin inferir probabilidades que no se proporcionan.|Reconstruye tu lista de destinos con los filtros y resultados actuales del mapa en vez de confiar en ubicaciones recordadas."),
  "pt-BR":onboardingSteps("Escolha um primeiro destino com os filtros do mapa e a lista acessível de resultados, limitando camadas densas aos marcadores necessários.|Compare os Pals por elementos e aptidões de trabalho atuais e escolha candidatos para as primeiras funções sem inventar níveis de desempenho.|Revise a ordem, os desbloqueios e os pré-requisitos de tecnologia antes de gastar pontos ou materiais para garantir que o próximo objetivo seja alcançável.|Defina trabalhos essenciais, níveis mínimos e limite da equipe no planejador de base e examine os candidatos gerados.|Escolha a receita exata, calcule a demanda direta e expandida de materiais e pare quando várias receitas ainda exigirem sua escolha.","Revise o catálogo atual de missões, seus objetivos e links de recompensas e crie sua própria lista para revisitar.|Compare pré-requisitos, desbloqueios e tecnologias dependentes antes de usar pontos ou materiais guardados.|Examine as etapas de expedição e as possíveis recompensas sem inferir probabilidades não fornecidas.|Refaça sua lista de destinos com os filtros e resultados atuais do mapa em vez de depender de locais lembrados."),
  "ru-RU":onboardingSteps("Выберите первую цель с помощью фильтров карты и доступного списка результатов, ограничив плотные слои только нужными метками.|Сравните Палов по их текущим стихиям и пригодности к работе и выберите кандидатов на первые роли без выдуманных уровней эффективности.|Проверьте порядок технологий, открытия и требования до траты очков или материалов, чтобы следующая цель была достижима.|Задайте в планировщике базы необходимые рабочие роли, минимальные уровни и лимит команды, затем проверьте предложенных кандидатов.|Выберите точный рецепт, рассчитайте прямую и развёрнутую потребность в материалах и остановитесь там, где выбор между рецептами остаётся за вами.","Просмотрите текущий каталог заданий, цели и связи с наградами, затем составьте собственный список для повторного посещения.|Сравните требования, открытия и зависимые технологии до использования сохранённых очков или материалов.|Изучите этапы экспедиций и возможные награды, не выводя отсутствующие вероятности.|Составьте список целей заново по текущим фильтрам и результатам карты, а не по запомнившимся местам."),
  "id-ID":onboardingSteps("Pilih tujuan pertama dengan filter peta dan daftar hasil yang mudah diakses, serta batasi lapisan padat pada penanda yang diperlukan.|Bandingkan Pal berdasarkan elemen dan work suitability saat ini, lalu pilih kandidat untuk peran awal tanpa membuat tier performa.|Tinjau urutan teknologi, unlock, dan prasyarat sebelum memakai poin atau bahan agar target berikutnya dapat dicapai.|Atur peran kerja penting, level minimum, dan batas tim di perencana base, lalu periksa kandidat yang dihasilkan.|Pilih resep yang tepat, hitung kebutuhan bahan langsung dan terurai, lalu berhenti ketika beberapa resep masih memerlukan pilihan Anda.","Tinjau katalog quest saat ini, objektif, dan tautan hadiah, lalu buat daftar kunjungan ulang Anda sendiri.|Bandingkan prasyarat, unlock, dan teknologi lanjutan sebelum memakai poin atau bahan yang disimpan.|Periksa tahap ekspedisi dan kandidat hadiah tanpa menyimpulkan probabilitas yang tidak tersedia.|Susun ulang daftar tujuan dari filter dan hasil peta saat ini, bukan dari lokasi yang diingat."),
  "th-TH":onboardingSteps("เลือกจุดหมายแรกด้วยตัวกรองแผนที่และรายการผลลัพธ์ที่เข้าถึงได้ โดยจำกัดเลเยอร์ที่หนาแน่นให้เหลือเฉพาะหมุดที่ต้องการ|เปรียบเทียบ Pal ตามธาตุและความถนัดงานปัจจุบัน แล้วเลือกผู้สมัครสำหรับบทบาทแรกโดยไม่สร้างระดับประสิทธิภาพขึ้นเอง|ตรวจสอบลำดับเทคโนโลยี สิ่งที่ปลดล็อก และข้อกำหนดก่อนใช้แต้ม หรือวัตถุดิบ เพื่อให้เป้าหมายถัดไปเข้าถึงได้|กำหนดบทบาทงานที่จำเป็น เลเวลขั้นต่ำ และขีดจำกัดทีมในเครื่องมือวางแผนฐาน แล้วตรวจสอบผู้สมัครที่สร้างขึ้น|เลือกสูตรที่แน่นอน คำนวณวัตถุดิบโดยตรงและแบบขยาย และหยุดเมื่อมีหลายสูตรที่ยังต้องให้คุณเลือก","ตรวจสอบรายการเควสต์ เป้าหมาย และลิงก์รางวัลปัจจุบัน แล้วทำรายการที่คุณต้องการกลับไปดูเอง|เปรียบเทียบข้อกำหนด สิ่งที่ปลดล็อก และเทคโนโลยีที่ต่อเนื่องก่อนใช้แต้ม หรือวัตถุดิบที่เก็บไว้|ตรวจสอบขั้นของการสำรวจและรางวัลที่เป็นไปได้ โดยไม่อนุมานความน่าจะเป็นที่ไม่ได้ระบุ|สร้างรายชื่อจุดหมายใหม่จากตัวกรองและผลลัพธ์แผนที่ปัจจุบัน แทนการพึ่งพาตำแหน่งที่จำได้"),
  "tr-TR":onboardingSteps("Harita filtreleri ve erişilebilir sonuç listesiyle ilk hedefi seçin; yoğun katmanları yalnızca gereken işaretlerle sınırlandırın.|Palları güncel elementleri ve iş uygunluklarıyla karşılaştırın; performans kademesi uydurmadan ilk roller için aday seçin.|Puan veya malzeme harcamadan önce teknoloji sırasını, açılanları ve ön koşulları inceleyerek sonraki hedefin erişilebilir olduğunu doğrulayın.|Üs planlayıcıda gerekli iş rollerini, asgari seviyeleri ve takım sınırını belirleyip üretilen adayları inceleyin.|Kesin tarifi seçin, doğrudan ve genişletilmiş malzeme ihtiyacını hesaplayın ve birden çok tarif seçiminizi gerektirdiğinde durun.","Güncel görev kataloğunu, hedefleri ve ödül bağlantılarını inceleyip kendi yeniden ziyaret listenizi oluşturun.|Biriktirilmiş puan veya malzemeleri kullanmadan önce teknoloji ön koşullarını, açılanları ve bağımlı teknolojileri karşılaştırın.|Verilmeyen olasılıkları çıkarsamadan keşif aşamalarını ve olası ödülleri inceleyin.|Hatırlanan konumlara güvenmek yerine güncel harita filtreleri ve sonuçlarından hedef listenizi yeniden oluşturun."),
  "vi-VN":onboardingSteps("Chọn điểm đến đầu tiên bằng bộ lọc bản đồ và danh sách kết quả dễ tiếp cận, đồng thời thu hẹp các lớp dày đặc về những dấu mốc cần thiết.|So sánh Pal theo nguyên tố và khả năng làm việc hiện tại, rồi chọn ứng viên cho các vai trò đầu tiên mà không tự đặt hạng hiệu suất.|Xem thứ tự công nghệ, nội dung mở khóa và điều kiện trước khi dùng điểm hoặc vật liệu để bảo đảm mục tiêu tiếp theo có thể đạt được.|Đặt vai trò công việc thiết yếu, cấp tối thiểu và giới hạn đội trong công cụ lập kế hoạch căn cứ, rồi xem các ứng viên được tạo.|Chọn đúng công thức, tính nhu cầu vật liệu trực tiếp và mở rộng, rồi dừng ở nơi nhiều công thức vẫn cần bạn lựa chọn.","Xem danh mục nhiệm vụ hiện tại, mục tiêu và liên kết phần thưởng, rồi tự tạo danh sách cần xem lại.|So sánh điều kiện, nội dung mở khóa và công nghệ phụ thuộc trước khi dùng điểm hoặc vật liệu đã giữ lại.|Xem các giai đoạn viễn chinh và phần thưởng có thể có mà không suy diễn xác suất không được cung cấp.|Tạo lại danh sách điểm đến từ bộ lọc và kết quả bản đồ hiện tại thay vì dựa vào vị trí đã nhớ."),
  "pl-PL":onboardingSteps("Wybierz pierwszy cel za pomocą filtrów mapy i dostępnej listy wyników, ograniczając gęste warstwy do potrzebnych znaczników.|Porównaj Pale według bieżących żywiołów i przydatności do pracy, a następnie wybierz kandydatów do pierwszych ról bez wymyślania poziomów wydajności.|Sprawdź kolejność technologii, odblokowania i wymagania przed wydaniem punktów lub materiałów, aby następny cel był osiągalny.|Ustaw w planerze bazy niezbędne role pracy, minimalne poziomy i limit drużyny, a następnie sprawdź wygenerowanych kandydatów.|Wybierz dokładną recepturę, oblicz bezpośrednie i rozwinięte zapotrzebowanie na materiały i zatrzymaj się, gdy kilka receptur nadal wymaga twojego wyboru.","Przejrzyj aktualny katalog zadań, cele i powiązania nagród, a następnie utwórz własną listę do ponownego sprawdzenia.|Porównaj wymagania, odblokowania i technologie zależne przed użyciem zachowanych punktów lub materiałów.|Sprawdź etapy ekspedycji i możliwe nagrody bez wnioskowania o niepodanych prawdopodobieństwach.|Zbuduj listę celów ponownie z aktualnych filtrów i wyników mapy, zamiast polegać na zapamiętanych miejscach."),
};
export const guideOnboardingStepLabelsProvenance=Object.fromEntries(Object.keys(guideOnboardingStepLabels).map(locale=>[locale,"gpt"])) as Record<Locale,"gpt">;
