export const guideCopyProvenance=Object.fromEntries(Object.keys(guideCopy).map(locale=>[locale,"gpt"])) as Record<Locale,"gpt">;

export const guideRoute=(slug:string)=>`guides/${slug}`;
export const findGuide=(route:string)=>guideDefinitions.find(guide=>guideRoute(guide.slug)===route);
